//! The Loom runtime (ADR 0021 §4).
//!
//! Native Loom programs call this library through a C ABI: the heap objects behind
//! `String`, `Bytes`, `Array` and `Map`, buffered standard output, number formatting
//! (spec §7.12) and panics. Generic collections know their element type only through a
//! [`TypeInfo`] descriptor generated by the code generator.
//!
//! This crate is linked into the `loom` binary for the JIT and built as a static library
//! for programs compiled ahead of time.

#![allow(
    unsafe_code,
    reason = "the runtime implements the memory model native code relies on"
)]

pub mod array;
pub mod map;
pub mod num;
pub mod ops;
pub mod sched;
pub mod string;

use std::io::Write;
use std::sync::Mutex;

